<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';require_once __DIR__.'/admin-ui.php';require_once __DIR__.'/blog-lib.php';$u=require_admin();$db=blog_db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$id=(int)($_POST['id']??0);$a=$_POST['action']??'';$q=$db->prepare('SELECT * FROM posts WHERE id=?');$q->execute([$id]);$p=$q->fetch();if(!$p||!post_owner($u,$p)) {http_response_code(403);exit('Not permitted.');}$next=['publish'=>'published','unpublish'=>'draft','archive'=>'archived','restore'=>'draft'][$a]??null;if($next&&($a!=='publish'||post_publishable($u))&&($a!=='unpublish'||post_publishable($u))){$db->prepare('UPDATE posts SET status=?,published_at=CASE WHEN ?="published" THEN CURRENT_TIMESTAMP ELSE published_at END,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$next,$next,$id]);audit($db,$u,$a,'post',$id,['status'=>$next]);}}
$where=[];$args=[];$search=trim($_GET['q']??'');$status=$_GET['status']??'';$cat=(int)($_GET['category']??0);if($search){$where[]='(p.title LIKE ? OR p.slug LIKE ?)';$args[]='%'.$search.'%';$args[]='%'.$search.'%';}if(in_array($status,['draft','published','archived'],true)){$where[]='p.status=?';$args[]=$status;}if($cat){$where[]='p.category_id=?';$args[]=$cat;}if($u['role']==='author'){$where[]='p.author_id=?';$args[]=$u['id'];}$sql='SELECT p.*,c.name category,u.name author FROM posts p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN users u ON u.id=p.author_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.updated_at DESC';$st=$db->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$cats=$db->query('SELECT id,name FROM categories WHERE status="active" ORDER BY name')->fetchAll();admin_layout_start('Posts','posts',$u);?><div class="bar"><div><h1>Blog posts</h1><p>Draft, publish, archive, and manage SEO safely.</p></div><a class="btn" href="/admin/post-edit.php">New post</a></div><form class="card" method="get"><div class="grid"><div><label>Search</label><input name="q" value="<?=htmlspecialchars($search)?>" placeholder="Title or slug"></div><div><label>Status</label><select name="status"><option value="">All statuses</option><?php foreach(['draft','published','archived']as$s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach?></select><label>Category</label><select name="category"><option value="">All categories</option><?php foreach($cats as$c):?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=htmlspecialchars($c['name'])?></option><?php endforeach?></select><button class="btn">Filter</button></div></div></form><section class="card"><table><thead><tr><th>Title</th><th>Slug</th><th>Category</th><th>Author</th><th>Status</th><th>Published</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as$p):?><tr><td><?=htmlspecialchars($p['title'])?></td><td><?=htmlspecialchars($p['slug'])?></td><td><?=htmlspecialchars($p['category']??'—')?></td><td><?=htmlspecialchars($p['author']??'—')?></td><td><?=$p['status']?></td><td><?=$p['published_at']??'—'?></td><td><?=$p['updated_at']?></td><td><?php if(post_owner($u,$p)):?><a href="/admin/post-edit.php?id=<?=$p['id']?>">Edit</a><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$p['id']?>"><?php if($p['status']==='draft'&&post_publishable($u)):?><button name="action" value="publish" class="btn">Publish</button><?php elseif($p['status']==='published'&&post_publishable($u)):?><button name="action" value="unpublish" class="btn alt">Unpublish</button><?php elseif($p['status']==='archived'):?><button name="action" value="restore" class="btn">Restore</button><?php endif?><?php if($p['status']!=='archived'):?><button name="action" value="archive" class="btn alt">Archive</button><?php endif?></form><?php endif?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="8">No posts found.</td></tr><?php endif?></tbody></table></section><?php admin_layout_end();
